// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;

    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(address attacker, address recipient) public {
        vm.assume(attacker != address(0));
        vm.assume(recipient != address(0));

        uint256 seedAmount = 1 ether;
        vm.deal(address(this), seedAmount);
        (bool sent, ) = address(c).call{value: seedAmount}("");
        require(sent);

        uint256 before = address(c).balance;
        vm.assume(before > 0);

        vm.prank(attacker);
        bool ok;
        try c.withdrawAll(recipient) {
            ok = true;
        } catch {
            ok = false;
        }

        if (attacker != address(this)) {
            assertTrue(address(c).balance == before);
        } else {
            assertTrue(address(c).balance == 0 || address(c).balance == before);
        }
    }
}
